"Bu faturayı stoktan düş (eşleşen malzemelerden çıkış)": "Diese Rechnung vom Bestand abbuchen (Abgang von den passenden Materialien)",
"Bu görev tanımını okudum, anladım; görevimle ilgili İSG eğitimlerini aldım ve belirtilen kurallara uyacağımı taahhüt ederim. Bir nüshası tarafıma teslim edilmiştir.": "Ich habe diese Aufgabenbeschreibung gelesen und verstanden; ich habe die auf meine Aufgabe bezogenen Arbeitsschutzschulungen erhalten und verpflichte mich, die genannten Regeln einzuhalten. Ein Exemplar wurde mir ausgehändigt.",
"Bu güncelleme küçük iyileştirmeler ve düzeltmeler içeriyor. Son sürümün notları:": "Dieses Update enthält kleinere Verbesserungen und Korrekturen. Hinweise zur letzten Version:",
