"Bu kurallar tüm kullanıcılara uygulanır: şifre değiştirme, giriş, oturum süresi, kaba kuvvet kilidi ve PIN.": "Diese Regeln gelten für alle Benutzer: Passwortänderung, Anmeldung, Sitzungsdauer, Brute-Force-Sperre und PIN.",
