  "Arazi planı alınıyor…": "Geländeplan wird geladen…",
  "Gerçek arazi · yükseklik {a}…{b} m · ev {h} m MSL": "Reales Gelände · Höhe {a}…{b} m · Home {h} m MSL",
  "{b} bina · {f} orman · {w} su · {r} pist": "{b} Gebäude · {f} Wälder · {w} Gewässer · {r} Pisten",
  "OSM verisi alınamadı: binalar/orman/su gösterilmiyor ({e})": "OSM-Daten nicht verfügbar: Gebäude/Wald/Wasser fehlen ({e})",
  "Gerçek kipte seçili merkezin çevresi gerçek yükseklik, uydu görüntüsü ve OpenStreetMap binalarıyla kurulur; veriler ilk kullanımda indirilip sunucuda önbelleklenir.": "Im Realmodus wird die Umgebung des gewählten Zentrums aus realen Höhen, Satellitenbildern und OpenStreetMap-Gebäuden aufgebaut; Daten werden beim ersten Gebrauch geladen und serverseitig gecacht.",
  "Prosedürel dünya: tohumlu rastgele arazi, binalar ve ağaçlar.": "Prozedurale Welt: Gelände, Gebäude und Bäume aus Seed.",
  "Gövde": "Rumpf",
  "Delta kanat": "Deltaflügel",
  "Caymaz V3: ürettiğimiz uçağın STEP modelinden · Delta kanat: arkadan itişli uçan kanat": "Caymaz V3: aus dem STEP-Modell unseres Flugzeugs · Deltaflügel: Nurflügler mit Druckpropeller",
  "Google 3B (fotogerçekçi)": "Google 3D (fotorealistisch)",
  "Google 3B (fotogerçekçi) · ev {h} m MSL": "Google 3D (fotorealistisch) · Home {h} m MSL",
  "Google 3B karoları yükleniyor… %{p}": "Google-3D-Kacheln werden geladen… {p} %",
  "Google 3B verisi alınamadı: {e} → prosedürele düşüldü": "Google-3D-Daten nicht verfügbar: {e} → auf prozedural zurückgefallen",
  "Google 3B kipinde çevre Google Photorealistic 3D Tiles ile fotogerçekçi kurulur (binalar ve ağaçlar karoların içinde); karolar tarayıcıya doğrudan Google’dan gelir, sunucuda önbelleklenmez; atıf zorunludur. Ev irtifası açık yükseklik verisinden alınır.": "Im Google-3D-Modus wird die Umgebung fotorealistisch aus Google Photorealistic 3D Tiles aufgebaut (Gebäude und Bäume sind Teil der Kacheln); die Kacheln kommen direkt von Google in den Browser und werden nicht auf dem Server zwischengespeichert; die Quellenangabe ist Pflicht. Die Home-Höhe stammt aus offenen Höhendaten.",
  "yükleniyor %{p}": "lädt {p} %",
  "Google 3B yer ofseti {o} m (karo yüzeyi ↔ ev irtifası)": "Google-3D-Bodenversatz {o} m (Kacheloberfläche ↔ Home-Höhe)",
  "Dron tipi için görsel gövde: dahili modeller her zaman vardır; sistemdeki STEP/GLB/OBJ dosyaları ya da yüklediğiniz model seçilince tarayıcıda GLB'ye dönüştürülür.": "Visueller Rumpf für den Drohnentyp: eingebaute Modelle sind immer vorhanden; STEP/GLB/OBJ-Dateien im System oder ein hochgeladenes Modell werden bei Auswahl im Browser nach GLB konvertiert.",
  "Model": "Modell",
  "⬆ Model yükle": "⬆ Modell hochladen",
  "🗂 Sistemdeki dosyalardan ekle": "🗂 Aus Systemdateien hinzufügen",
