  "Bu modelin GLB'si henüz üretilmedi; yazma izni olan bir kullanıcı seçince tarayıcıda dönüştürülür.": "Die GLB dieses Modells wurde noch nicht erzeugt; sie wird im Browser konvertiert, wenn ein Benutzer mit Schreibrecht sie auswählt.",
