  "Yüz bulunamadı — kameraya bakın": "Kein Gesicht erkannt — in die Kamera schauen", "Başınızı hafifçe çevirin": "Kopf leicht drehen", "Yüz doğrulandı": "Gesicht bestätigt",
  "Şimdi PIN kodunuzu girin": "Geben Sie jetzt Ihre PIN ein", "Hoş geldiniz": "Willkommen", "Yüz doğrulanamadı": "Gesicht konnte nicht bestätigt werden", "Yüz doğrulandı · PIN kodunuzu girin": "Gesicht bestätigt · PIN eingeben",
  "Yüz tanıtma": "Gesicht einrichten", "Mevcut şifreniz": "Ihr aktuelles Passwort", "İkinci taramayı başlat": "Zweiten Scan starten", "Başla": "Starten", "İkinci tarama": "Zweiter Scan",
  "Farklı ışık ve açılarda ikinci bir tarama tanımayı daha güvenilir yapar. Gözlük takıyorsanız bu kez çıkarabilirsiniz.": "Ein zweiter Scan bei anderem Licht und anderen Winkeln macht die Erkennung zuverlässiger. Brillenträger können die Brille diesmal abnehmen.",
  "Giriş ekranında şifre ya da PIN yerine yüzünüzle giriş yapın. Yüzünüz birkaç açıdan taranır; yalnızca matematiksel bir özet şifrelenerek saklanır, fotoğraf saklanmaz.": "Melden Sie sich statt mit Passwort oder PIN mit Ihrem Gesicht an. Ihr Gesicht wird aus mehreren Winkeln gescannt; gespeichert wird nur eine verschlüsselte mathematische Zusammenfassung, kein Foto.",
  "Başınızı yavaşça daire çizerek çevirin": "Bewegen Sie den Kopf langsam im Kreis", "Halka tamamlanınca yüzünüz tanıtılır": "Sobald der Ring vollständig ist, ist Ihr Gesicht eingerichtet",
  "Güvenlik için mevcut şifreniz": "Zur Sicherheit Ihr aktuelles Passwort", "Tamamla": "Abschließen", "{n} / 9 açı": "{n} / 9 Winkel", "Yüzünüzü tanıtın": "Gesicht einrichten",
  "Süre doldu": "Zeit abgelaufen", "Yeniden başlatın": "Bitte neu starten", "Bağlantı hatası": "Verbindungsfehler",
  "Farklı bir yüz algılandı — yalnızca kendi yüzünüzü tanıtın": "Ein anderes Gesicht wurde erkannt — richten Sie nur Ihr eigenes Gesicht ein", "Önce doğrudan kameraya bakın": "Schauen Sie zuerst direkt in die Kamera",
  "Kaydediliyor…": "Wird gespeichert…", "İkinci tarama tamamlandı": "Zweiter Scan abgeschlossen", "Yüzünüz tanıtıldı": "Ihr Gesicht ist eingerichtet", "{n} açıdan kaydedildi": "Aus {n} Winkeln gespeichert",
  "İkinci taramayı yap (önerilir)": "Zweiten Scan durchführen (empfohlen)", "Bitti": "Fertig", "Hazır": "Bereit",
  "Yüz ile giriş sistem yöneticisi tarafından kapatılmış.": "Die Gesichtsanmeldung wurde vom Systemadministrator deaktiviert.",
  "Yüz tanıma motoru bu sunucuda kurulu değil; yöneticinize başvurun.": "Die Gesichtserkennung ist auf diesem Server nicht installiert; wenden Sie sich an Ihren Administrator.",
  "Bu cihazda bir kez şifreyle giriş yaptıktan sonra giriş ekranında adınıza dokunup yüzünüzle girebilirsiniz. Yüzünüzün yalnızca şifrelenmiş matematiksel özeti saklanır; fotoğraf saklanmaz.": "Nach einer Passwortanmeldung auf diesem Gerät tippen Sie auf dem Anmeldebildschirm auf Ihren Namen und melden sich mit dem Gesicht an. Gespeichert wird nur eine verschlüsselte mathematische Zusammenfassung Ihres Gesichts, kein Foto.",
  "Yüz tanıtılmamış": "Kein Gesicht eingerichtet", "Yüz tanıtıldı · {n} açı": "Gesicht eingerichtet · {n} Winkel", "Yalnız yüz": "Nur Gesicht", "Yüz + PIN": "Gesicht + PIN",
  "Önce PIN ile girişi açın": "Aktivieren Sie zuerst die PIN-Anmeldung", "Yüz doğrulandıktan sonra PIN de istenecek": "Nach der Gesichtsprüfung wird zusätzlich die PIN verlangt", "Yalnız yüz ile giriş": "Anmeldung nur mit Gesicht",
  "Giriş kipi": "Anmeldemodus", "Yüz doğrulanınca ek olarak PIN sorulur (daha güvenli)": "Nach der Gesichtsprüfung wird zusätzlich die PIN abgefragt (sicherer)", "Yüz doğrulanınca doğrudan giriş": "Direkte Anmeldung nach der Gesichtsprüfung",
  "Yeniden tanıt": "Neu einrichten", "Yüz verisini sil": "Gesichtsdaten löschen",
  "Kayıtlı yüz özeti kalıcı olarak silinir; giriş ekranında yüz ile giriş kapanır. İstediğiniz zaman yeniden tanıtabilirsiniz.": "Die gespeicherte Gesichtszusammenfassung wird dauerhaft gelöscht; die Gesichtsanmeldung auf dem Anmeldebildschirm wird deaktiviert. Sie können sie jederzeit neu einrichten.",
  "Sil": "Löschen", "Yüz verisi silindi": "Gesichtsdaten gelöscht", "Kullanıcı bilgileri, şifre, PIN, yüz ile giriş": "Benutzerdaten, Passwort, PIN, Gesichtsanmeldung", "Şifre kuralları, giriş, PIN ve yüz": "Passwortregeln, Anmeldung, PIN und Gesicht",
  "Güvenilir cihazda kamerayla (Face ID tarzı) giriş. Yüz özeti sunucuda şifreli saklanır; kullanıcı Kişisel Ayarlar › Hesap’tan tanıtır.": "Anmeldung per Kamera (Face-ID-Stil) auf vertrauenswürdigen Geräten. Die Gesichtszusammenfassung wird verschlüsselt auf dem Server gespeichert; Benutzer richten sie unter Persönliche Einstellungen › Konto ein.",
  "Yüz ile girişe izin ver": "Gesichtsanmeldung erlauben", "Kapatılırsa kimse yüzle giremez ve yeni yüz tanıtılamaz; mevcut kayıtlar silinmez": "Wenn deaktiviert, kann sich niemand per Gesicht anmelden oder ein neues Gesicht einrichten; vorhandene Einträge bleiben erhalten",
  "Eşleşme eşiği": "Übereinstimmungsschwelle", "Kosinüs benzerliği × 100. 45 önerilir; düşük = daha hoşgörülü (yanlış kabul riski), yüksek = daha sıkı (ışık değişiminde ret).": "Kosinus-Ähnlichkeit × 100. 45 empfohlen; niedriger = toleranter (Risiko falscher Akzeptanz), höher = strenger (Ablehnung bei wechselndem Licht).",
  "Canlılık adımı (baş çevirme)": "Lebendigkeitsprüfung (Kopfdrehung)", "Eşleşmeden sonra rastgele bir yöne hafifçe bakılması istenir; fotoğrafla kandırmayı zorlaştırır": "Nach der Übereinstimmung wird gebeten, kurz in eine zufällige Richtung zu schauen; erschwert Täuschung mit einem Foto",
