  "Aramaya uyan parametre yok": "Kein Parameter passt zur Suche",
  "Henüz kayıtlı parametre yok. Sanal dronla uçarken HEPGO panelinden ya da Mission Planner'dan değiştirilen her parametre burada kalıcı olur; aynı dronla SITL yeniden açılınca geri yüklenir.": "Noch keine gespeicherten Parameter. Jeder Parameter, der beim Flug mit der virtuellen Drohne über das HEPGO-Panel oder Mission Planner geändert wird, bleibt hier erhalten und wird beim Neustart von SITL mit derselben Drohne wiederhergestellt.",
